import * as THREE from 'three';
import {NodeIO} from '@gltf-transform/core';
import {KHRONOS_EXTENSIONS} from '@gltf-transform/extensions';
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';

function extrema(curve){
  const groups=[];
  for(let i=0;i<curve.length;i++){
    if(!groups.length||Math.abs(curve[i]-groups.at(-1).v)>1e-7)groups.push({lo:i,hi:i,v:curve[i]});
    else groups.at(-1).hi=i;
  }
  const maxima=groups.filter((g,i)=>i===0||i===groups.length-1||g.v>groups[i-1].v&&g.v>groups[i+1].v);
  return groups.filter((g,i)=>i>0&&i<groups.length-1&&g.v<groups[i-1].v&&g.v<groups[i+1].v).map(g=>{
    const left=maxima.filter(m=>m.hi<g.lo).at(-1),right=maxima.find(m=>m.lo>g.hi);
    const smaller=Math.min(left.v,right.v);
    return {bins:[g.lo,g.hi],valueM:g.v,leftMaximumM:left.v,rightMaximumM:right.v,prominenceM:smaller-g.v,depthFraction:(smaller-g.v)/smaller};
  });
}
async function measure(file){
  const bytes=await readFile(file),doc=await new NodeIO().registerExtensions(KHRONOS_EXTENSIONS).readBinary(bytes),rt=doc.getRoot(),nodes=rt.listNodes();
  const skin=rt.listSkins()[0],joints=skin.listJoints(),names=joints.map(j=>j.getName()),ibm=skin.getInverseBindMatrices();
  const mats=joints.map((j,i)=>new THREE.Matrix4().fromArray(j.getWorldMatrix()).multiply(new THREE.Matrix4().fromArray(ibm.getElement(i,[]))));
  const verts=[],triangles=[],parents=[];
  const find=i=>{while(parents[i]!==i){parents[i]=parents[parents[i]];i=parents[i];}return i;};
  for(const node of nodes)for(const prim of node.getMesh()?.listPrimitives()??[]){
    const base=verts.length,P=prim.getAttribute('POSITION'),J=prim.getAttribute('JOINTS_0'),W=prim.getAttribute('WEIGHTS_0'),C=prim.getAttribute('COLOR_0');
    for(let i=0;i<P.getCount();i++){
      const p=new THREE.Vector3(...P.getElement(i,[])),js=J.getElement(i,[]),ws=W.getElement(i,[]),world=new THREE.Vector3(),weights={};
      for(let k=0;k<4;k++)if(ws[k]>0){world.add(p.clone().applyMatrix4(mats[js[k]]).multiplyScalar(ws[k]));weights[names[js[k]]]=(weights[names[js[k]]]??0)+ws[k];}
      parents.push(verts.length);verts.push({p:world.toArray(),weights,c:C?.getElement(i,[])??[0,0,0],mesh:node.getName()});
    }
    const indices=prim.getIndices()?.getArray()??Array.from({length:P.getCount()},(_,i)=>i);
    for(let i=0;i<indices.length;i+=3){
      const t=[base+indices[i],base+indices[i+1],base+indices[i+2]];triangles.push(t);
      parents[find(t[1])]=find(t[0]);parents[find(t[2])]=find(t[0]);
    }
  }
  const tris=triangles.map(t=>({v:t.map(i=>verts[i].p),component:find(t[0]),indices:t}));
  function section(y,filter=()=>true){
    const out=[];
    for(const tri of tris){
      if(!filter(tri))continue;
      const hits=[];
      for(let i=0;i<3;i++){
        const a=tri.v[i],b=tri.v[(i+1)%3];
        if((a[1]<=y&&b[1]>y)||(b[1]<=y&&a[1]>y)){
          const t=(y-a[1])/(b[1]-a[1]);hits.push([a[0]+(b[0]-a[0])*t,a[2]+(b[2]-a[2])*t]);
        }
      }
      if(hits.length===2)out.push({a:hits[0],b:hits[1],component:tri.component});
    }
    return out;
  }
  function radius(segments,cx,cz){
    const radii=[];
    for(let k=0;k<64;k++){
      const angle=(k+.371)/64*Math.PI*2,dx=Math.cos(angle),dz=Math.sin(angle),groups=new Map();
      for(const {a,b,component} of segments){
        const ax=a[0]-cx,az=a[1]-cz,bx=b[0]-cx,bz=b[1]-cz,ha=dx*az-dz*ax,hb=dx*bz-dz*bx;
        if((ha<=0&&hb>0)||(hb<=0&&ha>0)){
          const u=ha/(ha-hb),t=dx*(ax+(bx-ax)*u)+dz*(az+(bz-az)*u);
          if(!groups.has(component))groups.set(component,[]);groups.get(component).push(t);
        }
      }
      const intervals=[];
      for(const hits of groups.values()){
        hits.sort((a,b)=>a-b);
        for(let i=0;i+1<hits.length;i+=2)intervals.push([hits[i],hits[i+1]]);
      }
      intervals.sort((a,b)=>a[0]-b[0]);
      const merged=[];
      for(const ab of intervals){if(merged.length&&ab[0]<=merged.at(-1)[1]+1e-7)merged.at(-1)[1]=Math.max(merged.at(-1)[1],ab[1]);else merged.push([...ab]);}
      const containing=merged.find(ab=>ab[0]<=1e-6&&ab[1]>=-1e-6);
      radii.push(containing?Math.max(0,containing[1]):0);
    }
    return {radiusM:Math.sqrt(radii.reduce((s,r)=>s+r*r,0)/radii.length),missingRays:radii.filter(r=>r===0).length};
  }
  const feet=[];
  for(const leg of ['FR','FL','HR','HL']){
    const name=leg+'_Paw',region=verts.filter(v=>(v.weights[name]??0)>=.5),lowest=Math.min(...region.map(v=>v.p[1]));
    const patch=region.filter(v=>v.p[1]<=lowest+.003);
    const bound=(v,k)=>[Math.min(...v.map(v=>v.p[k])),Math.max(...v.map(v=>v.p[k]))];
    const px=bound(patch,0),pz=bound(patch,2);
    const bone=n=>joints[names.indexOf(n)].getWorldMatrix().slice(12,15);
    const paw=bone(name),path=[[paw[0],lowest,(pz[0]+pz[1])/2],paw,bone(leg+'_Ankle'),bone(leg+'_Lower'),bone(leg+'_Upper')];
    const curve=[];
    for(let i=0;i<40;i++){
      const y=lowest+(path.at(-1)[1]-lowest)*i/39,evalY=y+(i===0?1e-7:0);
      let j=0;while(j<path.length-2&&path[j+1][1]<y)j++;
      const a=path[j],b=path[j+1],t=(y-a[1])/(b[1]-a[1]),cx=a[0]+(b[0]-a[0])*t,cz=a[2]+(b[2]-a[2])*t;
      curve.push({heightM:y,...radius(section(evalY),cx,cz)});
    }
    const band=region.filter(v=>v.p[1]>=lowest+.003-1e-7&&v.p[1]<=lowest+.030+1e-7),bx=bound(band,0);
    const project=points=>{
      const bins=Array(16).fill(-Infinity);
      for(const p of points){const i=Math.max(0,Math.min(15,Math.floor((p[0]-bx[0])/(bx[1]-bx[0])*16)));bins[i]=Math.max(bins[i],p[2]-paw[2]);}
      return bins;
    };
    const vertexToe=project(band.map(v=>v.p));
    const projected=[];
    for(const tri of tris){
      if(!tri.indices.every(i=>(verts[i].weights[name]??0)>=.5))continue;
      let polygon=tri.v;
      for(const [plane,sign] of [[lowest+.003,1],[lowest+.030,-1]]){
        const next=[];
        for(let i=0;i<polygon.length;i++){
          const a=polygon[i],b=polygon[(i+1)%polygon.length],insideA=(a[1]-plane)*sign>=0,insideB=(b[1]-plane)*sign>=0;
          if(insideA)next.push(a);
          if(insideA!==insideB){const t=(plane-a[1])/(b[1]-a[1]);next.push(a.map((v,k)=>v+(b[k]-v)*t));}
        }
        polygon=next;
      }
      for(let j=0;j<polygon.length;j++){
        const a=polygon[j],b=polygon[(j+1)%polygon.length];projected.push(a);
        for(let k=1;k<16;k++){
          const x=bx[0]+(bx[1]-bx[0])*k/16,t=(x-a[0])/(b[0]-a[0]);
          if(t>0&&t<1){const p=a.map((v,k)=>v+(b[k]-v)*t);projected.push([x-1e-9,p[1],p[2]],[x+1e-9,p[1],p[2]]);}
        }
      }
    }
    const toe=project(projected),minima=toe.every(Number.isFinite)?extrema(toe).filter(m=>m.prominenceM>=.002):[];
    const grooves=minima.map(m=>({bins:m.bins,prominenceM:m.prominenceM,lowestHeightM:null}));
    const heightCurves=[];
    for(let step=0;step<=120;step++){
      const mm=step*.25;
      const y=lowest+mm/1000,segments=section(y,tri=>tri.indices.every(i=>(verts[i].weights[name]??0)>=.5)),points=[];
      for(const {a,b}of segments){
        points.push([a[0],y,a[1]],[b[0],y,b[1]]);
        for(let i=1;i<16;i++){
          const x=bx[0]+(bx[1]-bx[0])*i/16,t=(x-a[0])/(b[0]-a[0]);
          if(t>0&&t<1){const z=a[1]+(b[1]-a[1])*t;points.push([x-1e-9,y,z],[x+1e-9,y,z]);}
        }
      }
      const values=project(points),first=values.findIndex(Number.isFinite),last=values.findLastIndex(Number.isFinite);
      const finite=first>=0?values.slice(first,last+1):[];
      const minimaAt=finite.length>=3&&finite.every(Number.isFinite)?extrema(finite).filter(m=>m.prominenceM>=.002).map(m=>({...m,bins:m.bins.map(i=>i+first)})):[];
      heightCurves.push({heightM:mm/1000,minima:minimaAt});
      for(const g of grooves)if(g.lowestHeightM===null&&minimaAt.some(m=>m.bins[0]<=g.bins[1]+1&&m.bins[1]>=g.bins[0]-1))g.lowestHeightM=mm/1000;
    }
    const valleys=extrema(curve.map(p=>p.radiusM));
    feet.push({bone:name,limb:{curve,valleys,passes:curve.every(p=>p.missingRays===0)&&valleys.every(v=>v.depthFraction<=.12)},
      toes:{bandM:[.003,.030],widthM:bx[1]-bx[0],forwardExtentM:toe,vertexForwardExtentM:vertexToe,minima,grooves,grooveThresholdSamples:heightCurves.filter(row=>grooves.some(g=>g.lowestHeightM!==null&&Math.abs(row.heightM-g.lowestHeightM)<.00026)),passes:toe.every(Number.isFinite)&&grooves.length>=3&&grooves.every(g=>g.lowestHeightM!==null&&g.lowestHeightM<=.012)}});
  }
  const ears=['Ear_L','Ear_R'].map(name=>{
    const region=verts.filter(v=>(v.weights[name]??0)>=.99),shell=region.filter(v=>v.mesh.endsWith('_Anatomy')),tufts=region.filter(v=>!v.mesh.endsWith('_Anatomy')&&Math.max(...v.c.slice(0,3))<.08);
    const tip=Math.max(...shell.map(v=>v.p[1])),tuft=Math.max(...tufts.map(v=>v.p[1]));
    return {bone:name,earTipHeightM:tip,darkTuftHeightM:tuft,extensionM:tuft-tip,passes:tuft-tip>=.025};
  });
  const tailVertices=verts.filter(v=>Object.entries(v.weights).filter(([n])=>n.startsWith('Tail_')).reduce((s,[n,w])=>s+w,0)>.999);
  const groups=new Map();
  for(const v of tailVertices){
    const t=Object.entries(v.weights).reduce((s,[n,w])=>s+(n.startsWith('Tail_')?(Number(n.slice(5))-1)*w:0),0);
    const key=t.toFixed(6);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(v);
  }
  const rings=[...groups.entries()].sort((a,b)=>Number(a[0])-Number(b[0])).map(([t,vs])=>{
    const unique=[...new Map(vs.map(v=>[v.p.map(x=>x.toFixed(6)).join(','),v])).values()];
    return {parameter:Number(t)/3,centre:[0,1,2].map(k=>unique.reduce((s,v)=>s+v.p[k],0)/unique.length),colour:[0,1,2].map(k=>unique.reduce((s,v)=>s+v.c[k],0)/unique.length)};
  });
  const length=rings.slice(1).reduce((s,r,i)=>s+Math.hypot(...r.centre.map((x,k)=>x-rings[i].centre[k])),0);
  const meanColour=arr=>[0,1,2].map(k=>arr.reduce((s,r)=>s+r.colour[k],0)/arr.length);
  let distance=0;for(let i=0;i<rings.length;i++){if(i)distance+=Math.hypot(...rings[i].centre.map((x,k)=>x-rings[i-1].centre[k]));rings[i].arcFraction=distance/length;}
  const mid=meanColour(rings.filter(r=>r.arcFraction>=.35&&r.arcFraction<=.60)),distal=meanColour(rings.filter(r=>r.arcFraction>=.70));
  const luminance=c=>c[0]*.2126+c[1]*.7152+c[2]*.0722;
  function stationTop(z){
    let highest=-Infinity;
    for(const tri of tris){
      if(!tri.indices.every(i=>verts[i].mesh.endsWith('_Anatomy')))continue;
      for(let i=0;i<3;i++){
        const a=tri.v[i],b=tri.v[(i+1)%3];
        if((a[2]<=z&&b[2]>=z)||(b[2]<=z&&a[2]>=z)){
          if(Math.abs(b[2]-a[2])<1e-10)continue;
          const t=(z-a[2])/(b[2]-a[2]),x=a[0]+(b[0]-a[0])*t,y=a[1]+(b[1]-a[1])*t;
          if(Math.abs(x)<.09)highest=Math.max(highest,y);
        }
      }
    }
    return highest;
  }
  const sacrum=stationTop(-.40),scapula=stationTop(.31);
  return {file,sha256:createHash('sha256').update(bytes).digest('hex'),jointNames:names,clipNames:rt.listAnimations().map(a=>a.getName()),feet,ears,
    tail:{lengthM:length,midMeanLinearRGB:mid,distalMeanLinearRGB:distal,midLuminance:luminance(mid),distalLuminance:luminance(distal),rings,passes:length>=.12&&length<=.20&&luminance(distal)<luminance(mid)},
    haunch:{sacrumStationZM:-.40,scapulaStationZM:.31,sacrumTopM:sacrum,scapulaTopM:scapula,passes:sacrum>=scapula}};
}
console.log(JSON.stringify(await measure(process.argv[2])));
